local function a()if Config.LogAudit.path and Config.LogAudit.path~=''then return Config.LogAudit.path end;local b=GetResourcePath(GetCurrentResourceName())if type(b)~='string'or b==''then return nil end;local c=b:gsub('\\','/'):gsub('/resources/.*$','')local d=c:lower()if d:find('/txdata/',1,true)then return c..'/logs/fxserver.log'end;if d:match('/server%-data$')then local e=c:gsub('/server%-data$','')local f=GetConvar('serverProfile','default')if not f:match('^[%w_%-]+$')then f='default'end;return e..'/txData/'..f..'/logs/fxserver.log'end;return nil end;local function g(h)h=h:gsub('\27%[[%d;]*m',''):gsub('[%z\1-\8\11\12\14-\31]','')h=h:gsub('([Tt]oken%s*[:=]%s*)[^%s,;]+','%1<oculto>'):gsub('([Pp]assword%s*[:=]%s*)[^%s,;]+','%1<oculto>'):gsub('([Ss]ecret%s*[:=]%s*)[^%s,;]+','%1<oculto>')return Doctor.safe(h):sub(1,500)end;local function i(h)local j,k,l=h:match('SCRIPT ERROR:%s*@?([^:]+%.lua):(%d+):%s*(.*)')if j then return j..':'..k,l end;local m,n=h:match('No such export%s+([%w_%-]+) in resource ([%w_%-]+)')if m then return n,'Falta el export '..m end;if h:find('SCRIPT ERROR:',1,true)or h:find('Error parsing script',1,true)or h:find('Failed to load script',1,true)or h:find('Could not load script',1,true)then return'fxserver.log',h end end;Doctor.register({id='erroreslog',title='Errores registrados en la consola',run=function(o)if not Config.LogAudit.enabled then return end;local p=a()if p and not p:lower():match('[/\\]fxserver%.log$')then p=nil end;if not p or not io or not io.open then o:add({severity='informacion',title='No se pudo localizar el registro de FXServer',where='config.lua (Config.LogAudit.path)',why='NX_ServerDoctor necesita el archivo fxserver.log de txAdmin para revisar errores que ya aparecieron en la consola.',fix={'Configura la ruta absoluta del fxserver.log de tu perfil txAdmin. Sin un archivo de log, FiveM no expone al recurso el historial de errores de consola.'}})return end;local j=io.open(p,'rb')if not j then o:add({severity='informacion',title='No se encontró el registro fxserver.log',where='config.lua (Config.LogAudit.path)',why='No se pudo abrir la ruta detectada. El servidor puede no usar txAdmin o guardar los logs en otro perfil.',fix={'Configura Config.LogAudit.path con la ruta absoluta a txAdmin/<perfil>/logs/fxserver.log.'}})return end;local q=j:seek('end')or 0;local r=math.max(65536,tonumber(Config.LogAudit.maxBytes)or 2097152)j:seek('set',math.max(0,q-r))local s=j:read('*a')or''j:close()local t,u={},{}for h in s:gmatch('[^\r\n]+')do local v,l=i(h)if v then local w=v..'\0'..l;if not t[w]then t[w]={where=v,message=l,count=0}u[#u+1]=w end;t[w].count=t[w].count+1 end end;table.sort(u)local x=math.min(math.max(1,tonumber(Config.LogAudit.maxFindings)or 50),math.max(1,tonumber(Config.Limits.findingsPerCheck)or 40))for y=1,math.min(#u,x)do local z=t[u[y]]o:add({severity='error',title='Error encontrado en el registro de FXServer',where=g(z.where),why=g(z.message)..(z.count>1 and(' (repetido %d veces en el tramo revisado)'):format(z.count)or''),fix={'Corrige el error en ese recurso/archivo y reinícialo; vuelve a ejecutar /nxcheck para revisar el registro actualizado.'}})o:step()end;if#u==0 then o:add({severity='informacion',title='No hay errores conocidos en el registro reciente',where='txAdmin/logs/fxserver.log',why=('Se revisaron hasta %d KB del final del registro.'):format(math.ceil(math.min(q,r)/1024)),fix={}})elseif#u>x then o:add({severity='informacion',title='Se alcanzó el límite de errores del registro',where='config.lua (Config.LogAudit.maxFindings)',why=('Se muestran %d de %d errores distintos encontrados.'):format(x,#u),fix={'Aumenta Config.LogAudit.maxFindings para mostrar más.'}})end end})